// SPDX-License-Identifier: MIT
pragma solidity >=0.5.0 <0.9.0;

import "./Tally.sol";

contract Counter {
    uint256 public count;

    function bump(uint256 amount) public {
        count = Tally.add(count, amount);
    }
}

